mapper.select:
SELECT transaction_type
FROM categories
WHERE id = #{categoryId}
AND user_id = #{userId}
AND is_active = TRUE

mapper.update:
UPDATE transactions
SET
category_id = #{categoryId},
amount = #{amount},
expense_type = #{expenseType, jdbcType=VARCHAR},
memo = #{memo, jdbcType=VARCHAR}
WHERE id = #{id}
AND user_id = #{userId}

mapper.delete:
DELETE FROM transactions
WHERE id = #{id}
AND user_id = #{userId}
